#include <Adafruit_SSD1306.h>
#include <iostream>
#include <stdexcept>
#include <sstream>
int main(){try{
    Adafruit_SSD1306 display(128,64);display.clearDisplay();display.setTextColor(SSD1306_WHITE);display.setTextSize(1);display.setCursor(0,0);display.print("Hi");int pixels=0;for(int y=0;y<8;++y)for(int x=0;x<12;++x)pixels+=display.getPixel(x,y);if(pixels<10||display.getCursorX()!=12)throw std::runtime_error("GFX cursor/text rendering failed");int16_t x,y;uint16_t w,h;display.getTextBounds("Hi",0,0,&x,&y,&w,&h);if(w!=12||h!=8)throw std::runtime_error("text bounds failed");display.println();if(display.getCursorX()!=0||display.getCursorY()!=8)throw std::runtime_error("Print newline failed");display.print(123,HEX);if(display.getCursorX()!=12)throw std::runtime_error("Print numeric format failed");
    display.clearDisplay();display.drawCircle(20,20,5,SSD1306_WHITE);if(!display.getPixel(25,20)||!display.getPixel(20,15)||display.getPixel(20,20))throw std::runtime_error("circle rendering failed");display.fillCircle(20,20,5,SSD1306_WHITE);if(!display.getPixel(20,20))throw std::runtime_error("fill circle failed");display.drawPixel(20,20,SSD1306_INVERSE);if(display.getPixel(20,20))throw std::runtime_error("pixel inversion failed");display.fillTriangle(40,10,50,30,30,30,SSD1306_WHITE);if(!display.getPixel(40,20))throw std::runtime_error("triangle fill failed");
    display.clearDisplay();display.setRotation(1);display.drawPixel(5,10,SSD1306_WHITE);if(display.width()!=64||display.height()!=128||!display.getPixel(5,10)||!(display.getBuffer()[117]&(1<<5)))throw std::runtime_error("rotation mapping failed");
    uint8_t bitmap[]={0xf0};GFXglyph glyph[]={ {0,2,2,3,0,0} };GFXfont font={bitmap,glyph,'A','A',3};display.setRotation(0);display.clearDisplay();display.setFont(&font);display.setCursor(0,0);display.print("A");if(!display.getPixel(0,0)||!display.getPixel(1,1)||display.getCursorX()!=3)throw std::runtime_error("custom font failed");display.setFont();
    Adafruit_SSD1306 small(128,32);small.setRotation(1);if(small.width()!=32||small.height()!=128)throw std::runtime_error("128x32 dimensions failed");small.drawPixel(0,127,SSD1306_WHITE);if(!small.getPixel(0,127))throw std::runtime_error("small OLED pixel mapping failed");
    thinker::standalone=true;std::ostringstream messages;auto* old=std::cout.rdbuf(messages.rdbuf());
    Adafruit_SSD1306 scrolling(128,64);const bool begun=scrolling.begin(SSD1306_SWITCHCAPVCC);scrolling.drawPixel(0,0,SSD1306_WHITE);scrolling.display();scrolling.startscrollright(0,7);messages.str("");thinker::advance(100000);const auto scrolled=messages.str();scrolling.dim(true);const bool dim=messages.str().find(" 250\n")!=std::string::npos;std::cout.rdbuf(old);
    if(!begun||scrolled.find("FRAME 60 0001")==std::string::npos||!scrolling.getPixel(0,0)||!dim)throw std::runtime_error("automatic scroll, drawing buffer preservation or brightness failed");
    std::cout<<"Original GFX text, print, bounds, shapes, custom fonts, rotation and 128x32 passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
